def region_corners(hi, vi, h_seps, v_seps):
    """Get global coordinates of 4 corners of a region"""
    if hi == 0:
        r_min, r_max = h_seps[0]-1, h_seps[0]
    elif hi == len(h_seps)-1:
        r_min, r_max = h_seps[-1], h_seps[-1]+1
